public abstract class Object {
  float x, y, z, mass, radius, width, height, depth;

  String type;

  int col;

  BObject body;

  public void display(boolean showOutlines) {

    Transform trans = body.rigidBody.getWorldTransform(new Transform());
    Matrix4f mat = new Matrix4f();
    trans.getMatrix(mat);

    if (type.equals("Box")) {
      BBox b = (BBox) body;
      pushMatrix();
      translate(b.getPosition().x, b.getPosition().y, b.getPosition().z);
      applyMatrix(
        mat.m00, mat.m01, mat.m02, 0,
        mat.m10, mat.m11, mat.m12, 0,
        mat.m20, mat.m21, mat.m22, 0,
        0, 0, 0, 1
        );
      fill(col);
      if (showOutlines) {
        stroke(0);
      } else {
        noStroke();
      }
      box(width, height, depth);
      popMatrix();
      noStroke();
    } else if (type.equals("Sphere")) {
      BSphere s = (BSphere) body;
      pushMatrix();
      translate(s.getPosition().x, s.getPosition().y, s.getPosition().z);
      applyMatrix(
        mat.m00, mat.m01, mat.m02, 0,
        mat.m10, mat.m11, mat.m12, 0,
        mat.m20, mat.m21, mat.m22, 0,
        0, 0, 0, 1
        );
      fill(col);
      if (showOutlines) {
        stroke(0);
      } else {
        noStroke();
      }
      sphere(radius);
      popMatrix();
      noStroke();
    }

    if (this instanceof DynamicObject) {
      x = body.getPosition().x;
      y = body.getPosition().y;
      z = body.getPosition().z;
    }
  }

  public void displayBRigid() {
    body.display();
  }
}
class Slider {
    float x, y, width, height;
    float minValue, maxValue, step;
    float currentValue;
    boolean isDragging = false;

    Slider(float x, float y, float width, float height, float minValue, float maxValue, float step, float initialValue) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.step = step;
        this.currentValue = initialValue;
    }

    public void display() {
        fill(200);
        rect(x, y, width, height);
        fill(100);
        ellipse(map(currentValue, minValue, maxValue, x, x + width), y + height / 2, height, height);
    }

    public void update() {
        if (isDragging && mouseX >= x && mouseX <= x + width && mouseY >= y && mouseY <= y + height) {
            float mouseValue = map(mouseX, x, x + width, minValue, maxValue);
            currentValue = round(mouseValue / step) * step;
            currentValue = constrain(currentValue, minValue, maxValue);
            isDragging = true;
        } else if (mouseJustReleased) {
            isDragging = false;
        }
    }
}
public class StaticObject extends Object {
  StaticObject(float x, float y, float z, float width, float height, float depth, int col) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.width = width;
    this.height = height;
    this.depth = depth;
    mass = 0;
    this.type = "Box";
    this.col = col;
    body = new BBox(PhysicsCalculator.this, 0, width, height, depth);
    body.setPosition(x, y, z);
    physics.addBody(body);
  }

  StaticObject(float x, float y, float z, float radius, int col) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.radius = radius;
    mass = 0;
    this.type = "Sphere";
    this.col = col;
    body = new BSphere(PhysicsCalculator.this, 0, x, y, z, radius);
    physics.addBody(body);
  }
}
public class Textbox extends Button {

    Button leftButton, rightButton;

    boolean selected;

    float value;

    String tempLabel;

    Textbox(int x, int y, int w, int h, String label) {
        super(x, y, w, h, label);
        leftButton = new Button(x - 30, y, 30, h, "-");
        rightButton = new Button(x + w, y, 30, h, "+");
        selected = false;

        value = Float.parseFloat(label);
        tempLabel = label;
    }

    @Override public 
    void display() {
        super.display();
        leftButton.display();
        rightButton.display();
    }

    @Override public 
    void update() {
        super.update();
        leftButton.update();
        rightButton.update();
        if (isClicked()) {
            selected = true;
            tempLabel = label;
            label = "";
            typing = true;
            selectedTextbox = this;
        }

        if (leftButton.isClicked()) {
            value -= 10.0f;
            label = String.format("%.1f", value);
        }
        if (rightButton.isClicked()) {
            value += 10.0f;
            label = String.format("%.1f", value);
        }

    }

    public void escape() {
        selected = false;
        typing = false;
        selectedTextbox = null;
        label = tempLabel;
    }

    public void enter() {
        try {
            value = Float.parseFloat(label);
            label = String.format("%.1f", value);
        } catch (NumberFormatException e) {
            label = tempLabel;
        }
        selected = false;
        typing = false;
        selectedTextbox = null;
    }
}


